interface Cart { readonly items: readonly Item[]; readonly total: number; }

const withItem = (cart: Cart, item: Item): Cart => ({
  items: [...cart.items, item],            // build the complete next value
  total: cart.total + item.price,
});

store.setState(prev => withItem(prev, item));  // commit once, from the latest snapshot
